// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzz the from, value and a single recipient address; the _tos length must be >0
    function testFuzz_property(address from, address to, uint256 v) public {
        // bound the recipient so it's a contract we deploy (EOAs have no code and the low-level call would succeed but do nothing)
        // Deploy a benign callee that returns true for transferFrom signature so the internal calls succeed.
        BenignCallee callee = new BenignCallee();

        // construct a single-element _tos array in memory
        address[] memory tos = new address[](1);
        tos[0] = to;

        // We must ensure _tos.length > 0 (it is), and we want the callee's address passed as caddress
        // Call c.transfer and capture its returned boolean using try/catch (public function returns bool)
        bool ok;
        try c.transfer(from, address(callee), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // should not revert because BenignCallee handles the call and require(_tos.length>0) holds
            ok = false;
        }

        // The universal property: the reference implementation always returns true for any admissible input
        // (non-empty _tos and a callee that does not cause the inner require to fail). The mutant returns false
        // and thus will make this assertion fail for some inputs. Assert that c.transfer returned true.
        assertTrue(ok);
    }
}

// Minimal benign callee that implements transferFrom(address,address,uint256) and returns normally
contract BenignCallee {
    // matching signature: transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
